    def find_person(self):
        data = self.mydb.read_customers_by(name = self.lineEdit_name.text(), id = self.lineEdit_id.text())
        self.customer_list = [{'Id':i['id'],'Name':i['username'],'Pic':i['pic']} for i in data]
        self.tableWidget.clear()
        self.fill_table()
        self.pushButton_select.setEnabled(False)
        self.label_pic.setPixmap(QtGui.QPixmap("pic/nopic.png"))

    def active_change(self):
        row = self.tableWidget.currentRow()
        self.active_user = self.customer_list[row]
        # print(self.active_user)
        self.label_pic.setPixmap(QtGui.QPixmap(self.active_user['Pic']))
        self.pushButton_select.setEnabled(True)

    def load_Persons(self):
        data = self.mydb.read_customers()
        # print(data,'**')
        self.customer_list = [{'Id':i['id'],'Name':i['username'],'Pic':i['pic']} for i in data]
        # print(self.customer_list,'***')
        self.fill_table()

    def fill_table(self):
        rows = len(self.customer_list)
        cols= ['Id','Name','Pic']
        self.tableWidget.setRowCount(rows)
        # item = QtWidgets.QTableWidgetItem()
        for row in range(rows):
            item = QtWidgets.QTableWidgetItem(str(row+1))
            self.tableWidget.setVerticalHeaderItem(row,item)
        for index , col_name in enumerate(cols):
            item = QtWidgets.QTableWidgetItem(col_name)
            self.tableWidget.setHorizontalHeaderItem(index,item)
        for row in range(rows):
            for col in range(len(cols)):
                item = QtWidgets.QTableWidgetItem(str(self.customer_list[row][cols[col]]))
                # item.setFlags(QtCore.Qt.NoItemFlags)
                self.tableWidget.setItem(row,col,item)      

